-- Migration 0026 — `messaging_config` (the D-04 activation switch) and the four
-- `send_ledger` delivery-receipt columns (MSG-01, Phase 4, plan 04-03).
--
-- GENERATED by drizzle-kit from src/db/schema/messaging-config.ts and
-- src/db/schema/send-ledger.ts, then renamed from its random tag
-- (`0026_curious_the_captain`), re-tagged in meta/_journal.json, and
-- hand-extended with the GRANT block. The generated DDL itself is UNEDITED —
-- see below, because that is a change from 0025 and the reason matters.
--
-- ── NO DRIFT STATEMENTS THIS TIME, AND THAT IS 0025's SNAPSHOT WORKING ───────
--
-- Migration 0025 had to delete three statements the generator emitted, unasked,
-- against `cadences`: migrations 0023 and 0024 are hand-written, so the drizzle
-- snapshot did not know about the indexes they create and the generator treated
-- the difference as new work. Applying it would have dropped
-- `cadences_one_per_opened_event` and then failed on a 42P07 — the G-3-2 replay
-- guarantee silently gone, at a statement-breakpoint boundary that does not roll
-- the drop back.
--
-- 0025's SNAPSHOT recorded all three indexes correctly, which is precisely what
-- stops the generator re-emitting them, and this generation confirms it: the
-- diff below touches `messaging_config` and `send_ledger` and nothing else.
-- Verified by reading, not assumed — the next hand-written migration re-opens
-- the same trap for the one after it.
--
-- ── THE JOURNAL STAMP WAS CHECKED AGAINST THE DATABASE, NOT ONLY THE FILE ────
--
-- The trap 0025 hit is not detectable inside the journal: drizzle's migrator
-- applies only entries strictly NEWER than the newest `created_at` already in
-- `drizzle.__drizzle_migrations`, and a concurrent worktree had applied a
-- wall-clock-stamped migration (1787936781812) to this shared hosted database
-- that `main`'s journal has never seen. A journal that is perfectly monotonic in
-- itself can still be entirely behind the database, and `migrate` then exits 0
-- having applied NOTHING.
--
-- So before applying this one, the applied head was read directly:
--   applied head 1787940000000 (0025_inbound_messages)
--   this entry   1787974203903 (wall clock at generation)
-- Strictly newer, so it applies. The generated wall-clock stamp is kept rather
-- than hand-picked into the `…9082xx00000` series precisely BECAUSE the series
-- is what fell behind last time.
--
-- ── WHY `NULLS NOT DISTINCT` IS A CONSTRAINT AND NOT A BARE INDEX ────────────
--
-- drizzle-orm 0.45.2 exposes `nullsNotDistinct()` on the UNIQUE CONSTRAINT
-- builder only; the index builder has no such method. Postgres implements a
-- UNIQUE constraint AS a unique index, so the guarantee is identical and
-- `ON CONFLICT (channel, tenant_id)` infers this arbiter exactly as it would a
-- bare index. The clause is load-bearing rather than tidy: `tenant_id IS NULL`
-- is THE GLOBAL DEFAULT ROW, Postgres treats NULLs as distinct by default, and
-- without this any number of "global" sms rows could exist — with the read
-- returning whichever one the planner picked, i.e. this system sending from an
-- arbitrary one of two numbers with no error anywhere.
--
-- ── THE DELIVERY COLUMNS ADD FACTS AND CHANGE NO SEMANTICS ──────────────────
--
-- Four NULLABLE columns on `send_ledger`, and NOTHING ELSE on that table: the
-- `outcome` column and its vocabulary are untouched. A delivery receipt answers
-- "did the carrier reach the handset", `outcome` answers "did the provider
-- accept it from us", and folding the former into the latter would turn an
-- unconfirmed delivery into a `failed` send — whose obvious follow-up action is
-- a retry, which is how a customer gets messaged twice. See the schema header.
--
-- They need no grant of their own: Postgres table privileges cover every column,
-- including ones added later, and `send_ledger`'s grants were set in 0017.

CREATE TABLE "messaging_config" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" uuid,
	"channel" text NOT NULL,
	"from_address" text,
	"reply_to" text,
	"business_name" text,
	"enabled" boolean DEFAULT false NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "messaging_config_channel_tenant_uniq" UNIQUE NULLS NOT DISTINCT("channel","tenant_id"),
	CONSTRAINT "messaging_config_channel_known" CHECK (channel IN ('sms', 'email'))
);
--> statement-breakpoint
ALTER TABLE "messaging_config" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "send_ledger" ADD COLUMN "delivery_status" text;--> statement-breakpoint
ALTER TABLE "send_ledger" ADD COLUMN "delivery_detail" text;--> statement-breakpoint
ALTER TABLE "send_ledger" ADD COLUMN "delivered_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "send_ledger" ADD COLUMN "delivery_updated_at" timestamp with time zone;--> statement-breakpoint
CREATE POLICY "messaging_config_member_or_operator_access" ON "messaging_config" AS PERMISSIVE FOR ALL TO "authenticated" USING ((tenant_id IS NOT NULL AND has_tenant_access(tenant_id)) OR (tenant_id IS NULL AND is_operator())) WITH CHECK ((tenant_id IS NOT NULL AND has_tenant_access(tenant_id)) OR (tenant_id IS NULL AND is_operator()));--> statement-breakpoint

-- ── TABLE PRIVILEGES ────────────────────────────────────────────────────────
--
-- The sixth restatement of 0003's rule. drizzle-kit models tables and policies;
-- it does not model GRANTs, and Postgres checks PRIVILEGES BEFORE ROW-LEVEL
-- SECURITY — so a table with a perfect policy and no grant returns
-- `42501 permission denied`, an ERROR rather than an empty result, which leaks
-- the table's existence and breaks the property that denial and absence are
-- indistinguishable.
--
-- REVOKE-THEN-GRANT, following 0005/0007/0011/0017/0025. Hosted Supabase installs
-- ALTER DEFAULT PRIVILEGES at bootstrap and silently hands anon and authenticated
-- the full set — including TRUNCATE, WHICH IS NOT SUBJECT TO RLS, so no policy
-- test could ever catch it. A fresh `supabase start` database (what CI runs) has
-- no such default, so skipping the REVOKE makes CI and production disagree with
-- production being the permissive one.

REVOKE ALL ON public.messaging_config FROM anon;
--> statement-breakpoint
REVOKE ALL ON public.messaging_config FROM authenticated;
--> statement-breakpoint

-- READ-ONLY TO `authenticated`, exactly like the six cadence tables (0017) and
-- `inbound_messages` (0025).
--
-- THIS TABLE IS THE SWITCH THAT DECIDES WHETHER REAL SMS GOES TO REAL CUSTOMERS.
-- `enabled = true` on a row carrying a from-address is, by itself, the entire
-- activation — no deploy, no code change, effective on the next tick. A console
-- role holding UPDATE on this table would be a console role able to start
-- messaging every client's customers by flipping one boolean, and holding
-- INSERT would be the same power one row further back. So the console's
-- messaging page (04-06) writes through a server action on the service-role
-- repository, which is the same rule 0017 states for every D-16 control: an
-- operator turning sending on is one step of a decision, and the console role
-- holding a direct write is the console role able to perform a third of it.
--
-- anon gets SELECT so an unauthenticated read returns `[]` rather than 42501;
-- the policy above then returns zero rows, because `has_tenant_access()` admits
-- nothing for an anonymous JWT and `is_operator()` admits nothing for a user who
-- is not on the allowlist.
GRANT SELECT ON public.messaging_config TO anon;
--> statement-breakpoint
GRANT SELECT ON public.messaging_config TO authenticated;
--> statement-breakpoint
GRANT ALL ON public.messaging_config TO service_role;
